    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'answer-length recut, wellcorrelation refused: beginner module m06-the-correlation-workflow ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'wellcorrelation';
  if v_total <> 396 then raise exception 'answer-length recut, wellcorrelation refused: the course holds % questions, expected 396', v_total; end if;
  raise notice 'answer-length recut, wellcorrelation: % of 23 rows updated, the rest already carried the recut text', v_updated;
end $$;
